89	 * ⬡ LATENCY_TRACKER
90	 * Tracks rolling average of Ollama inference response times.
91	 */
92	class LatencyTracker {
93	    private latencies: number[] = [];
94	    private maxSamples = 10;
95	
96	    record(ms: number) {
97	        this.latencies.push(ms);
98	        if (this.latencies.length > this.maxSamples) this.latencies.shift();
99	    }
100	
101	    getAverage(): number {
102	        if (this.latencies.length === 0) return 0;
103	        return Math.round(this.latencies.reduce((a, b) => a + b, 0) / this.latencies.length);
104	    }
105	}
