107	class ForgeTelemetryTracker {
108	    private history: ForgeExecutionSnapshot[] = [];
109	    private maxEntries = 20;
110	
111	    record(snapshot: ForgeExecutionSnapshot) {
112	        this.history.push(snapshot);
113	        if (this.history.length > this.maxEntries) this.history.shift();
114	    }
115	
116	    getLatest() {
117	        return this.history[this.history.length - 1] || null;
118	    }
119	
120	    getRecent(limit: number = 5) {
121	        return this.history.slice(-limit);
122	    }
123	}
