400	    private async buildVaultContext(
401	        query: string,
402	        profile: RetrievalProfile,
403	        budget: ReasoningBudget
404	    ) {
405	        if (!this.db || !query) return '';
406	
407	        const limit = budget === 'cheap' ? 2 : budget === 'balanced' ? 3 : 4;
408	        const excerptLimit = budget === 'cheap' ? 500 : budget === 'balanced' ? 900 : 1300;
409	        const searchResults = await vectorSearch.search(this.db, query, { limit, profile });
410	
411	        if (searchResults.length === 0) return '';
412	
413	        console.log(`⬡ NEURAL_FORGE :: INJECTED_${searchResults.length}_KNOWLEDGE_NODES :: profile=${profile}`);
414	
415	        return [
416	            `[VAULT_CONTEXT_PROFILE]: ${profile}`,
417	            ...searchResults.map(node => {
418	                return `--- FILE: ${node.source_path} ---\n${node.content.substring(0, excerptLimit)}`;
419	            })
420	        ].join('\n\n');
421	    }
